type correctionMemberBurdenJoins[Q dialect.Joinable] struct {
	typ             string
	Correction      modAs[Q, correctionColumns]
	HouseholdMember modAs[Q, householdMemberColumns]
	PoolFundingRule modAs[Q, poolFundingRuleColumns]
}

func (j correctionMemberBurdenJoins[Q]) aliasedAs(alias string) correctionMemberBurdenJoins[Q] {
	return buildCorrectionMemberBurdenJoins[Q](buildCorrectionMemberBurdenColumns(alias), j.typ)
}

func buildCorrectionMemberBurdenJoins[Q dialect.Joinable](cols correctionMemberBurdenColumns, typ string) correctionMemberBurdenJoins[Q] {
	return correctionMemberBurdenJoins[Q]{
		typ: typ,
		Correction: modAs[Q, correctionColumns]{
			c: Corrections.Columns,
			f: func(to correctionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Corrections.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.CorrectionID),
					))
				}

				return mods
			},
		},
		HouseholdMember: modAs[Q, householdMemberColumns]{
			c: HouseholdMembers.Columns,
			f: func(to householdMemberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, HouseholdMembers.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.MemberID.EQ(cols.MemberID),
					))
				}

				return mods
			},
		},
		PoolFundingRule: modAs[Q, poolFundingRuleColumns]{
			c: PoolFundingRules.Columns,
			f: func(to poolFundingRuleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, PoolFundingRules.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.PoolID.EQ(cols.PoolID), to.Version.EQ(cols.FundingRuleVersion),
					))
				}

				return mods
			},
		},
	}
}
